const data = msg.payload;

function reject(reason) {
    msg.payload = {
        deviceId: data?.deviceId ?? null,
        reason: reason,
        receivedAtUtc: new Date().toISOString(),
        originalMessage: data
    };

    return [null, msg];
}

// 1. Validate JSON structure
if (!data || typeof data !== "object" || Array.isArray(data)) {
    return reject("invalid_json");
}

// 2. Validate schema version
if (data.schemaVersion !== 1) {
    return reject("invalid_schema_version");
}

// 3. Validate identifiers
if (
    typeof data.deviceId !== "string" ||
    !data.deviceId ||
    typeof data.bootId !== "string" ||
    !data.bootId ||
    !Number.isSafeInteger(data.sequence) ||
    data.sequence < 1
) {
    return reject("invalid_identifiers");
}

// 4. Validate MQTT topic
if (msg.topic !== `smartcare/v1/raw/${data.deviceId}`) {
    return reject("topic_device_mismatch");
}

// 5. Validate timestamp
if (
    typeof data.acquiredAtUtc !== "string" ||
    !Number.isFinite(Date.parse(data.acquiredAtUtc))
) {
    return reject("invalid_timestamp");
}

// 6. Validate quality
if (!["good", "invalid"].includes(data.quality)) {
    return reject("invalid_quality");
}

// 7. Validate sensor readings
if (data.quality === "good") {
    if (
        typeof data.heartRate !== "number" ||
        !Number.isFinite(data.heartRate) ||
        typeof data.spo2 !== "number" ||
        !Number.isFinite(data.spo2)
    ) {
        return reject("invalid_measurements");
    }

    // Technical plausibility checks, not medical thresholds
    if (
        data.heartRate <= 0 ||
        data.heartRate > 300 ||
        data.spo2 < 0 ||
        data.spo2 > 100
    ) {
        return reject("out_of_range");
    }
} else {
    if (
        data.heartRate !== null ||
        data.spo2 !== null ||
        typeof data.reason !== "string" ||
        !data.reason
    ) {
        return reject("invalid_missing_data_format");
    }
}

// 8. Detect duplicates within this Node-RED instance
const key = `${data.deviceId}:${data.bootId}`;
const lastSequence = flow.get(key);

if (lastSequence !== undefined && data.sequence <= lastSequence) {
    return reject("duplicate_or_old_sequence");
}

flow.set(key, data.sequence);

// Valid message
return [msg, null];
